1 │ /**
2 │  * Replay protection for client-supplied idempotency keys, so that retrying a request
3 │  * never moves money twice.
4 │  *
5 │  * <p>Exports one port: the operation that runs a body once per key and returns the
6 │  * first result to every later caller. Its storage and its concurrency handling are
7 │  * package-private — callers state the intent, not the mechanism.
8 │  */
9 │ package hu.bankmonitor.payments.idempotency;
