 11 │ import org.hibernate.annotations.JdbcTypeCode;
 12 │ import org.hibernate.type.SqlTypes;
 13 │ 
 14 │ import java.util.Objects;
 15 │ 
 16 │ /**
 17 │  * One client-supplied Idempotency Key, how far the work behind it has got, and the
 18 │  * response a repeat of it is owed.
 19 │  *
 20 │  * <p>The row is the lock. A unique constraint on {@link #getIdempotencyKey() the key} is
 21 │  * what serialises two requests arriving at once: both reach the insert, the database
 22 │  * refuses one of them, and the refusal — not a preceding read — is how the duplicate is
 23 │  * discovered. No application-level lock is involved anywhere in this slice.
 24 │  *
 25 │  * <p><b>The key is not the primary key, which is not an oversight.</b> Spring Data decides
 26 │  * whether {@code save} inserts or merges from whether the identifier is already set, so an
 27 │  * entity carrying an assigned key would be saved through {@code merge} — a {@code SELECT}
 28 │  * before every {@code INSERT}, and a silent {@code UPDATE} over a live claim when the row
 29 │  * it found belongs to somebody else's in-flight request. The surrogate identifier keeps
 30 │  * the claim a bare insert, and the named unique constraint keeps the mutual exclusion.
 31 │  *
 32 │  * <p>There is deliberately no timestamp. The status is the single answer to how far a
 33 │  * claim has got, and nothing here reads a clock yet; the reaper that would sweep claims
 34 │  * stranded by a crash is deferred, and is the ticket that should add the column with a
 35 │  * reader to shape it. {@code docs/deferred.md} has the reasoning.
 36 │  *
 37 │  * <p>There is also deliberately no mutator. Every transition this record makes is a
 38 │  * conditional or guarded update issued by {@link IdempotencyClaims}, because each one has
 39 │  * to be atomic against a concurrent duplicate — a setter would offer a second way to make
 40 │  * the same transition that quietly is not.
 41 │  */
 42 │ @Entity
 43 │ @Table(name = "idempotency_records")
 44 │ class IdempotencyRecord {
 45 │ 
 46 │ 	@Id
 47 │ 	@GeneratedValue(strategy = GenerationType.IDENTITY)
 48 │ 	private Long id;
 49 │ 
 50 │ 	@Column(length = 36)
 51 │ 	private String idempotencyKey;
 52 │ 
 53 │ 	@Column(length = 64)
 54 │ 	private String payloadHash;
 55 │ 
 56 │ 	// If left unannotated, JPA stores the status by ordinal. See design decision 29.
 57 │ 	@Enumerated(EnumType.STRING)
 58 │ 	@JdbcTypeCode(SqlTypes.VARCHAR)
 59 │ 	private IdempotencyStatus status;
 60 │ 
 61 │ 	@Column(length = 4000)
 62 │ 	private String responseBody;
 63 │ 
 64 │ 	protected IdempotencyRecord() {
 65 │ 		// required by JPA
 66 │ 	}
 67 │ 
 68 │ 	/**
 69 │ 	 * Claims a key, which is the only way a record comes into being: {@code IN_PROGRESS},
 70 │ 	 * with no response yet and the hash of the payload the claim was made for.
 71 │ 	 *
 72 │ 	 * <p>The hash is stored rather than the payload because the only question ever asked
 73 │ 	 * of it is whether a later request carrying this key means the same thing.
 74 │ 	 */
 75 │ 	IdempotencyRecord(String idempotencyKey, String payloadHash) {
 76 │ 		this.idempotencyKey = Objects.requireNonNull(idempotencyKey, "a claim is made on a key");
 77 │ 		this.payloadHash = Objects.requireNonNull(payloadHash, "a claim is made for a payload");
 78 │ 		this.status = IdempotencyStatus.IN_PROGRESS;
 79 │ 	}
 80 │ 
 81 │ 	Long getId() {
 82 │ 		return id;
 83 │ 	}
 84 │ 
 85 │ 	/** The value the client sent as {@code X-Idempotency-Key}. Unique across the table. */
 86 │ 	String getIdempotencyKey() {
 87 │ 		return idempotencyKey;
 88 │ 	}
 89 │ 
 90 │ 	/**
 91 │ 	 * What the request said, reduced to the one comparison made against it: a repeat of
 92 │ 	 * this key carrying a different hash is a client mistake, not a retry.
 93 │ 	 */
 94 │ 	String getPayloadHash() {
 95 │ 		return payloadHash;
 96 │ 	}
 97 │ 
 98 │ 	IdempotencyStatus getStatus() {
 99 │ 		return status;
100 │ 	}
101 │ 
102 │ 	/** The response the original request produced, present only once it has {@code SUCCEEDED}. */
103 │ 	String getResponseBody() {
104 │ 		return responseBody;
105 │ 	}
106 │ }

