  3 │ import org.junit.jupiter.api.AfterEach;
  4 │ import org.junit.jupiter.api.DisplayName;
  5 │ import org.junit.jupiter.api.Test;
  6 │ import org.springframework.beans.factory.annotation.Autowired;
  7 │ import org.springframework.boot.data.jpa.test.autoconfigure.DataJpaTest;
  8 │ import org.springframework.context.annotation.Import;
  9 │ import org.springframework.dao.DataAccessException;
 10 │ import org.springframework.dao.DataIntegrityViolationException;
 11 │ import org.springframework.jdbc.core.JdbcTemplate;
 12 │ import org.springframework.test.context.TestPropertySource;
 13 │ import org.springframework.transaction.IllegalTransactionStateException;
 14 │ import org.springframework.transaction.PlatformTransactionManager;
 15 │ import org.springframework.transaction.annotation.Propagation;
 16 │ import org.springframework.transaction.annotation.Transactional;
 17 │ import org.springframework.transaction.support.TransactionTemplate;
 18 │ 
 19 │ import javax.sql.DataSource;
 20 │ import java.sql.Connection;
 21 │ import java.sql.ResultSet;
 22 │ import java.sql.SQLException;
 23 │ import java.sql.Statement;
 24 │ 
 25 │ import static org.assertj.core.api.Assertions.assertThat;
 26 │ import static org.assertj.core.api.Assertions.assertThatCode;
 27 │ import static org.assertj.core.api.Assertions.assertThatThrownBy;
 28 │ 
 29 │ /**
 30 │  * Who holds an Idempotency Key is settled by the table, and every claim mechanic in this
 31 │  * slice is a way of asking it.
 32 │  *
 33 │  * <p>Two things are under test and they are not separable. One is the SQL: a unique
 34 │  * constraint that refuses a second live claim, and an update guarded on the status it is
 35 │  * leaving so that exactly one of several retries reclaims a failed key. The other is
 36 │  * <em>when each of those writes becomes visible</em>, which is the part that has no
 37 │  * meaning inside a single transaction — a claim nobody else can see has serialised
 38 │  * nothing, and a failure marked in the transaction that failed is not marked at all.
 39 │  *
 40 │  * <p>So this test is deliberately <b>not</b> transactional. {@code @DataJpaTest} wraps each
 41 │  * method in a transaction and rolls it back, which here would hide every distinction it
 42 │  * exists to draw: the claim, the reclaim and the failure marking all run in transactions of
 43 │  * their own, and a test that never commits cannot tell that apart from a test that does.
 44 │  * The cost is that rows survive the method that wrote them, so {@link #dropEveryClaim()}
 45 │  * clears the table by hand.
 46 │  *
 47 │  * <p>Concurrency itself is ticket 18's, against the running application. What is asserted
 48 │  * here is the mechanism those tests rely on, one caller at a time.
 49 │  */
 50 │ @DataJpaTest
 51 │ @Import(IdempotencyClaims.class)
 52 │ @Transactional(propagation = Propagation.NOT_SUPPORTED)
 53 │ @TestPropertySource(properties =
 54 │ 		// The application's own setting, restated because the migration is half of every
 55 │ 		// assertion below: `validate` has compared the entity against V3 before any run.
 56 │ 		"spring.jpa.hibernate.ddl-auto=validate")
 57 │ class TheTableDecidesWhoHoldsAKeyTest {
 58 │ 
 59 │ 	private static final String KEY = "6f9619ff-8b86-d011-b42d-00cf4fc964ff";
 60 │ 	private static final String PAYLOAD_HASH = "1".repeat(64);
 61 │ 	private static final String A_DIFFERENT_PAYLOAD_HASH = "2".repeat(64);
 62 │ 	private static final String STORED_RESPONSE = "{\"id\":42,\"status\":\"PENDING\"}";
 63 │ 
 64 │ 	@Autowired
 65 │ 	private IdempotencyClaims claims;
 66 │ 
 67 │ 	@Autowired
 68 │ 	private DataSource dataSource;
 69 │ 
 70 │ 	@Autowired
 71 │ 	private PlatformTransactionManager transactionManager;
 72 │ 
 73 │ 	private JdbcTemplate jdbc;
 74 │ 
 75 │ 	private TransactionTemplate operation;
 76 │ 
 77 │ 	@AfterEach
 78 │ 	void dropEveryClaim() {
 79 │ 		jdbc().update("DELETE FROM idempotency_records");
 80 │ 	}
 81 │ 
 82 │ 	/**
 83 │ 	 * The connection is opened <em>before</em> the claim and held open across it, so it is
 84 │ 	 * demonstrably not the one the claim used and demonstrably not sharing its transaction.
 85 │ 	 * Reading the row through it is the whole of what "another request can see the claim"
 86 │ 	 * means.
 87 │ 	 */
 88 │ 	@Test
 89 │ 	@DisplayName("a claim is committed before the caller returns, and another connection sees it")
 90 │ 	void aClaimIsCommittedBeforeTheCallerReturns() throws SQLException {
 91 │ 		try (Connection onlooker = dataSource.getConnection()) {
 92 │ 			claims.claim(KEY, PAYLOAD_HASH);
 93 │ 
 94 │ 			assertThat(readStatusThrough(onlooker)).isEqualTo("IN_PROGRESS");
 95 │ 		}
 96 │ 
 97 │ 		assertThat(storedPayloadHash()).isEqualTo(PAYLOAD_HASH);
 98 │ 		assertThat(storedResponseBody()).isNull();
 99 │ 	}
100 │ 
101 │ 	/**
102 │ 	 * The other half of "in a transaction of its own", and the half the test above cannot
103 │ 	 * see: with no caller's transaction open, {@code REQUIRED} would commit at the same
104 │ 	 * moment and the two propagations would be indistinguishable. Under a caller that rolls
105 │ 	 * back they come apart — a claim that had merely joined its caller would vanish with
106 │ 	 * it, handing the key to somebody else while the first request is still being answered.
107 │ 	 */
108 │ 	@Test
109 │ 	@DisplayName("a claim and a reclaim both outlive a caller's transaction that rolls back")
110 │ 	void aClaimAndAReclaimBothOutliveACallersTransactionThatRollsBack() {
111 │ 		assertThatThrownBy(() -> operation().executeWithoutResult(status -> {
112 │ 			claims.claim(KEY, PAYLOAD_HASH);
113 │ 			throw new IllegalStateException("the caller never got as far as the work");
114 │ 		})).isInstanceOf(IllegalStateException.class);
115 │ 
116 │ 		assertThat(storedStatus()).isEqualTo("IN_PROGRESS");
117 │ 
118 │ 		claims.markFailed(KEY);
119 │ 
120 │ 		assertThatThrownBy(() -> operation().executeWithoutResult(status -> {
121 │ 			claims.reclaimFailed(KEY);
122 │ 			throw new IllegalStateException("nor did the retry that took the key back");
123 │ 		})).isInstanceOf(IllegalStateException.class);
124 │ 
125 │ 		assertThat(storedStatus()).isEqualTo("IN_PROGRESS");
126 │ 	}
127 │ 
128 │ 	/**
129 │ 	 * The second half of the assertion is the one that matters: the surviving row still
130 │ 	 * carries the <em>first</em> payload hash. A claim implemented as a read followed by a
131 │ 	 * write would have found the row and updated it, which is silent, plausible, and hands
132 │ 	 * the key to the second caller while the first is still using it.
133 │ 	 */
134 │ 	@Test
135 │ 	@DisplayName("a second claim of a live key is refused by the constraint, not merged over it")
136 │ 	void aSecondClaimOfALiveKeyIsRefusedByTheConstraint() {
137 │ 		claims.claim(KEY, PAYLOAD_HASH);
138 │ 
139 │ 		assertThatThrownBy(() -> claims.claim(KEY, A_DIFFERENT_PAYLOAD_HASH))
140 │ 				.isInstanceOf(DataIntegrityViolationException.class)
141 │ 				.hasStackTraceContaining("IDEMPOTENCY_RECORDS_KEY_IS_UNIQUE");
142 │ 
143 │ 		assertThat(storedPayloadHash()).isEqualTo(PAYLOAD_HASH);
144 │ 	}
145 │ 
146 │ 	@Test
147 │ 	@DisplayName("exactly one of several retries reclaims a failed key")
148 │ 	void exactlyOneOfSeveralRetriesReclaimsAFailedKey() {
149 │ 		claims.claim(KEY, PAYLOAD_HASH);
150 │ 		claims.markFailed(KEY);
151 │ 
152 │ 		assertThat(claims.reclaimFailed(KEY)).isTrue();
153 │ 		assertThat(claims.reclaimFailed(KEY)).isFalse();
154 │ 		assertThat(storedStatus()).isEqualTo("IN_PROGRESS");
155 │ 	}
156 │ 
157 │ 	/** The guard, from the other side: a key somebody is still using is not up for grabs. */
158 │ 	@Test
159 │ 	@DisplayName("a key that has not failed cannot be reclaimed")
160 │ 	void aKeyThatHasNotFailedCannotBeReclaimed() {
161 │ 		claims.claim(KEY, PAYLOAD_HASH);
162 │ 
163 │ 		assertThat(claims.reclaimFailed(KEY)).isFalse();
164 │ 		assertThat(storedStatus()).isEqualTo("IN_PROGRESS");
165 │ 	}
166 │ 
167 │ 	@Test
168 │ 	@DisplayName("reclaiming a key nobody ever claimed matches nothing")
169 │ 	void reclaimingAKeyNobodyEverClaimedMatchesNothing() {
170 │ 		assertThat(claims.reclaimFailed(KEY)).isFalse();
171 │ 	}
172 │ 
173 │ 	/**
174 │ 	 * The reason {@code markFailed} runs in a transaction of its own, asserted as the
175 │ 	 * scenario rather than as the annotation: the operation being reported rolls back, and
176 │ 	 * the row it left behind has to say {@code FAILED} anyway. Joining that transaction
177 │ 	 * would undo the status write along with everything else and strand the key at
178 │ 	 * {@code IN_PROGRESS}, where no retry can ever reach it.
179 │ 	 */
180 │ 	@Test
181 │ 	@DisplayName("marking a key failed survives the rollback of the operation it reports")
182 │ 	void markingAKeyFailedSurvivesTheRollbackOfTheOperationItReports() {
183 │ 		claims.claim(KEY, PAYLOAD_HASH);
184 │ 
185 │ 		assertThatThrownBy(() -> operation().executeWithoutResult(status -> {
186 │ 			claims.markFailed(KEY);
187 │ 			throw new IllegalStateException("the reservation could not be made");
188 │ 		})).isInstanceOf(IllegalStateException.class);
189 │ 
190 │ 		assertThat(storedStatus()).isEqualTo("FAILED");
191 │ 		assertThat(claims.reclaimFailed(KEY)).isTrue();
192 │ 	}
193 │ 
194 │ 	/**
195 │ 	 * The same scenario with the opposite requirement, which is what makes the pair worth
196 │ 	 * writing: success is only success if the work committed. Design decision 4 bundles
197 │ 	 * this write with the money movement precisely so that a rollback takes both, leaving a
198 │ 	 * key that is still claimed rather than one promising a transfer nobody made.
199 │ 	 */
200 │ 	@Test
201 │ 	@DisplayName("marking a key succeeded is undone by the rollback of the operation it reports")
202 │ 	void markingAKeySucceededIsUndoneByTheRollbackOfTheOperationItReports() {
203 │ 		claims.claim(KEY, PAYLOAD_HASH);
204 │ 
205 │ 		assertThatThrownBy(() -> operation().executeWithoutResult(status -> {
206 │ 			claims.markSucceeded(KEY, STORED_RESPONSE);
207 │ 			throw new IllegalStateException("the reservation could not be made");
208 │ 		})).isInstanceOf(IllegalStateException.class);
209 │ 
210 │ 		assertThat(storedStatus()).isEqualTo("IN_PROGRESS");
211 │ 		assertThat(storedResponseBody()).isNull();
212 │ 	}
213 │ 
214 │ 	@Test
215 │ 	@DisplayName("a committed operation leaves the response for a repeat of the key to replay")
216 │ 	void aCommittedOperationLeavesTheResponseForARepeatOfTheKeyToReplay() {
217 │ 		claims.claim(KEY, PAYLOAD_HASH);
218 │ 
219 │ 		operation().executeWithoutResult(status -> claims.markSucceeded(KEY, STORED_RESPONSE));
220 │ 
221 │ 		assertThat(storedStatus()).isEqualTo("SUCCEEDED");
222 │ 		assertThat(storedResponseBody()).isEqualTo(STORED_RESPONSE);
223 │ 		assertThat(claims.reclaimFailed(KEY)).isFalse();
224 │ 	}
225 │ 
226 │ 	/**
227 │ 	 * {@code MANDATORY} turns the one mistake this design cannot survive into an exception
228 │ 	 * at the call site. Committing the success on its own would look like it worked, and
229 │ 	 * the divergence — a key reporting a transfer that was rolled back — only shows up
230 │ 	 * later, on a retry that replays a response for money that never moved.
231 │ 	 */
232 │ 	@Test
233 │ 	@DisplayName("marking a key succeeded outside the money-moving transaction is refused")
234 │ 	void markingAKeySucceededOutsideTheMoneyMovingTransactionIsRefused() {
235 │ 		claims.claim(KEY, PAYLOAD_HASH);
236 │ 
237 │ 		assertThatThrownBy(() -> claims.markSucceeded(KEY, STORED_RESPONSE))
238 │ 				.isInstanceOf(IllegalTransactionStateException.class);
239 │ 
240 │ 		assertThat(storedStatus()).isEqualTo("IN_PROGRESS");
241 │ 	}
242 │ 
243 │ 	/**
244 │ 	 * The cost of {@code REQUIRES_NEW}, written down where the next caller will meet it.
245 │ 	 * A new transaction cannot see the locks the suspended one holds, so reporting a
246 │ 	 * failure from inside the transaction that already wrote to this row — the obvious
247 │ 	 * place, a {@code catch} within the operation — blocks on a lock only that transaction
248 │ 	 * can release, and only once this call returns.
249 │ 	 *
250 │ 	 * <p>It waits out the database's lock timeout rather than deadlocking forever, which
251 │ 	 * is why this method takes a couple of seconds and why the failure arrives as a
252 │ 	 * timeout rather than as anything naming the real mistake. Worse, the row it leaves
253 │ 	 * behind is stranded at {@code IN_PROGRESS} — precisely the state {@code markFailed}
254 │ 	 * exists to prevent — so the symptom is a slow request followed by a key that can
255 │ 	 * never be retried.
256 │ 	 */
257 │ 	@Test
258 │ 	@DisplayName("marking a key failed from inside the transaction that wrote to it waits on itself")
259 │ 	void markingAKeyFailedFromInsideTheTransactionThatWroteToItWaitsOnItself() {
260 │ 		claims.claim(KEY, PAYLOAD_HASH);
261 │ 
262 │ 		assertThatThrownBy(() -> operation().executeWithoutResult(status -> {
263 │ 			claims.markSucceeded(KEY, STORED_RESPONSE);
264 │ 			claims.markFailed(KEY);
265 │ 		})).isInstanceOf(DataAccessException.class);
266 │ 
267 │ 		assertThat(storedStatus()).isEqualTo("IN_PROGRESS");
268 │ 	}
269 │ 
270 │ 	@Test
271 │ 	@DisplayName("the table refuses a status the domain has no name for")
272 │ 	void refusesAStatusTheDomainHasNoNameFor() {
273 │ 		assertThatThrownBy(() -> insertRecord("ABANDONED", null))
274 │ 				.hasStackTraceContaining("IDEMPOTENCY_RECORDS_STATUS_IS_KNOWN");
275 │ 	}
276 │ 
277 │ 	/** Both directions of one rule: a response means finished, and finished means a response. */
278 │ 	@Test
279 │ 	@DisplayName("the table refuses a stored response that disagrees with the status")
280 │ 	void refusesAResponseThatDisagreesWithTheStatus() {
281 │ 		assertThatThrownBy(() -> insertRecord("IN_PROGRESS", STORED_RESPONSE))
282 │ 				.hasStackTraceContaining("IDEMPOTENCY_RECORDS_RESPONSE_ONLY_WHEN_SUCCEEDED");
283 │ 		assertThatThrownBy(() -> insertRecord("SUCCEEDED", null))
284 │ 				.hasStackTraceContaining("IDEMPOTENCY_RECORDS_RESPONSE_ONLY_WHEN_SUCCEEDED");
285 │ 		assertThatCode(() -> insertRecord("SUCCEEDED", STORED_RESPONSE)).doesNotThrowAnyException();
286 │ 	}
287 │ 
288 │ 	private String readStatusThrough(Connection connection) throws SQLException {
289 │ 		try (Statement statement = connection.createStatement();
290 │ 				ResultSet row = statement.executeQuery(
291 │ 						"SELECT status FROM idempotency_records WHERE idempotency_key = '" + KEY + "'")) {
292 │ 			return row.next() ? row.getString(1) : null;
293 │ 		}
294 │ 	}
295 │ 
296 │ 	private String storedStatus() {
297 │ 		return readColumn("status");
298 │ 	}
299 │ 
300 │ 	private String storedPayloadHash() {
301 │ 		return readColumn("payload_hash");
302 │ 	}
